  const sm=[],visit7=[],visit30=[],visitProb=[],turns=days.map(r=>r.turn_deg),turnSm=[];for(let i=0;i<days.length;i++){sm.push(rolling(clean,i,state.params.smooth,Math.max(2,Math.floor(state.params.smooth/2)),a=>a.reduce((x,y)=>x+y,0)/a.length));visit7.push(rolling(visits,i,7,4,a=>a.reduce((x,y)=>x+y,0)/a.length));visit30.push(rolling(visits,i,30,15,a=>a.reduce((x,y)=>x+y,0)/a.length));visitProb.push(rolling(visitDay,i,30,15,a=>a.reduce((x,y)=>x+y,0)/a.length));turnSm.push(rolling(turns,i,state.params.smooth,Math.max(2,Math.floor(state.params.smooth/2)),a=>a.reduce((x,y)=>x+y,0)/a.length));}
  const zsp=[],zvi=[],zt=[];for(let i=0;i<days.length;i++){zsp.push(robustZ(sm,i,90,7,30,.001));zvi.push(robustZ(visit30,i,120,14,45,.005));zt.push(robustZ(turnSm,i,90,7,30,.01))}
