async function init(){try{const [a,b]=await Promise.all([fetch(DATA_URL),fetch(WATER_URL)]);if(!a.ok||!b.ok)throw Error('Project CSV files could not be loaded.');const raw=parseCSV(await a.text()).map(rawConvert),water=parseCSV(await b.text());window._raw=raw;state.duplicateRows=raw.length-new Set(raw.map(r=>`${r.collar}:${r.dateText}`)).size;state.water=water.map(r=>({permanent_id:r.permanent_id,use_group:r.use_group,nvisits:num(r.nvisits),n_collars:num(r.n_collars),months:['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'].map(m=>num(r[m]))}));state.collars=[...new Set(raw.map(r=>r.collar))].sort();state.collar=state.collars.includes('19842')?'19842':state.collars[0];state.rows=processRows(raw);state.episodes=makeEpisodes(state.rows);document.getElementById('episodeBadge').textContent=state.episodes.length;wireGlobal();render()}catch(e){app.innerHTML=`<div class="card"><span class="eyebrow">DATA LOAD ERROR</span><h2>Could not prepare the observatory</h2><p class="muted">${escapeHTML(e.message)} Confirm the local server is running from the project root and both source CSV files are in <code>data/</code>.</p></div>`}}
