function renderQuality(){const animals=state.collars.map(c=>{const g=state.rows.filter(r=>r.collar===c),o=g.filter(r=>r.observed),src=window._raw.filter(r=>r.collar===c);return{collar:c,first:g[0]?.dateText,last:g.at(-1)?.dateText,observed:o.length,span:g.length,missing:g.length-o.length,coverage:o.length/g.length*100,badCoords:src.filter(r=>r.qc_bad_coord).length,missingEnv:src.filter(r=>r.qc_missing_env).length,longVisit:src.filter(r=>r.qc_long_visit).length,interpolated:g.filter(r=>r.env_interpolated).length}});const s=stats(),tot=window._raw.length,bad=window._raw.filter(r=>r.qc_bad_coord).length,env=window._raw.filter(r=>r.qc_missing_env).length,long=window._raw.filter(r=>r.qc_long_visit).length;return pageHead('DATA QUALITY','Coverage & validation','Understand what was observed, what was missing, and where the signals need caution.')+`<div class="grid metrics">${metric('SOURCE ROWS',tot.toLocaleString(),`duplicate collar-days excluded: ${state.duplicateRows}`,true)}${metric('MISSING COLLAR-DAYS',s.missing.toLocaleString(),'outside source observation rows')}${metric('INVALID COORDINATE RANGES',bad,'flagged; values retained')}${metric('SOURCE ENVIRONMENT GAPS',env,'rows with ≥1 missing covariate')}${metric('VISIT DURATION >24H',long,'flagged; source values retained')}</div><div class="page-callout"><span class="callout-icon">◉</span><div><strong>Absence is not zero.</strong> Calendar days without a source row have unknown visits and coordinates. Visit-rate windows require a minimum number of observed values.</div></div>${card('Collar coverage',`Observed days / full calendar span · ${fmt(s.coverage)}% pooled calendar coverage`,`<div class="chart tall">${chartSVG([{name:'Coverage',color:COLORS.green,values:animals.map((r,i)=>({x:i,y:r.coverage,tip:`Collar ${r.collar} · ${r.observed}/${r.span} days`}))}],{height:285,labels:false,yTitle:'%'})}</div>`)}<div style="margin-top:13px">${card('Per-collar validation summary','Source-level QC flags are kept alongside values',`<div class="table-wrap"><table class="data-table"><thead><tr><th>COLLAR</th><th>FIRST DAY</th><th>LAST DAY</th><th>OBSERVED</th><th>SPAN</th><th>MISSING</th><th>COVERAGE</th><th>COORD FLAGS</th><th>ENV GAPS</th><th>LONG DURATION</th><th>ENV INTERP</th></tr></thead><tbody>${animals.map(r=>`<tr><td>${r.collar}</td><td>${r.first}</td><td>${r.last}</td><td>${r.observed}</td><td>${r.span}</td><td>${r.missing}</td><td>${fmt(r.coverage)}%</td><td>${r.badCoords}</td><td>${r.missingEnv}</td><td>${r.longVisit}</td><td>${r.interpolated}</td></tr>`).join('')}</tbody></table></div>`)}</div><div class="grid split equal" style="margin-top:13px"><div>${card('Signal quality over time','Selected collar · trailing 14-day observed coverage',`<div class="chart">${chartSVG([line(currentRows(),'quality14',COLORS.violet,'Coverage')],{height:220,yTitle:'share'})}</div>`)}</div><div>${card('Validation policy','How missingness and outliers are handled',`<div class="activity-list"><div class="activity-row"><span class="activity-mark"></span><div><b>No synthetic location fixes</b><small>Out-of-range coordinates are flagged and retained; movement is not calculated from them.</small></div></div><div class="activity-row"><span class="activity-mark warn"></span><div><b>Short environmental gaps</b><small>Up to three consecutive missing observed-day values carry forward the last measurement; source gaps stay flagged.</small></div></div><div class="activity-row"><span class="activity-mark"></span><div><b>Missing collar-days</b><small>Daily expansion marks absent days as unobserved; visits remain unknown, not zero.</small></div></div><div class="activity-row"><span class="activity-mark alert"></span><div><b>Long visit durations</b><small>Values above 24 h/day are flagged for review, not silently clipped in the source.</small></div></div></div>`)}</div></div>`}
function dateInput(g){const dates=g.filter(r=>r.observed).map(r=>r.dateText),preferred=state.selectedCutoff||state.agent?.cutoff,chosen=preferred&&preferred>=dates[0]&&preferred<=dates.at(-1)?preferred:dates.at(-1);return`<input id="cutoffDate" class="select" type="date" min="${dates[0]}" max="${dates.at(-1)}" value="${chosen}">`}
function evidenceAt(collar,cutoff,windowDays=30){const end=Date.parse(`${cutoff}T00:00:00Z`),rows=state.rows.filter(r=>r.collar===collar&&r.day<=end&&r.day>=end-windowDays*86400000&&r.observed),last=[...rows].reverse().find(r=>r.day===end)||[...rows].at(-1);if(!last)return{collar,cutoff,windowDays,available:false,reason:'No observed data on or before this cutoff in the selected window.'};const env=rows.filter(r=>Number.isFinite(r.rain_30d)),vis=rows.filter(r=>Number.isFinite(r.visit_rate_30d));return{collar,cutoff,windowDays,available:true,latest_observed_day:last.dateText,observed_days:rows.length,coverage:rows.length/windowDays,latest:{speed_centroid_km_day:last.speed_kmd,speed_robust_z:last.z_speed,visit_count:last.n_visits,visit_rate_7d:last.visit_rate_7d,visit_rate_30d:last.visit_rate_30d,visit_robust_z:last.z_visit,ndvi:last.ndvi,snow:last.snow,rain_30d:last.rain_30d,days_since_visit:last.days_since_visit,quality14:last.quality14,uncertainty:last.uncertainty,changepoint_speed:last.changepoint_speed,changepoint_visit:last.changepoint_visit,anomaly_flag:last.anomaly_flag},window_summary:{mean_speed_z:avg(rows.map(r=>r.z_speed)),mean_visit_z:avg(rows.map(r=>r.z_visit)),rain_30d_mean:avg(env.map(r=>r.rain_30d)),visit_rate_mean:avg(vis.map(r=>r.visit_rate_30d)),observed_count:rows.length}}}
