function callTool(name,args){const collar=String(args.collar||state.collar),cutoff=String(args.cutoff||currentRows().at(-1)?.dateText),cut=Date.parse(`${cutoff}T00:00:00Z`),base=evidenceAt(collar,cutoff,Number(args.window_days)||30);if(name==='inspect_animal_signals')return base;if(name==='inspect_environment'){const r=state.rows.filter(x=>x.collar===collar&&x.day<=cut&&x.observed).slice(-30);return{collar,cutoff,observed_days:r.length,mean_rain_7d:avg(r.map(x=>x.rain_7d)),mean_rain_30d:avg(r.map(x=>x.rain_30d)),mean_ndvi:avg(r.map(x=>x.ndvi)),mean_ndvi_deviation:avg(r.map(x=>x.ndvi_anom)),mean_snow:avg(r.map(x=>x.snow)),mean_temperature_c:avg(r.map(x=>x.temp_c)),environment_missing_rows:r.filter(x=>x.qc_missing_env).length,interpolated_rows:r.filter(x=>x.env_interpolated).length,note:'Descriptive covariates, not evidence of water availability or causal drivers.'}}if(name==='assess_data_quality'){const g=state.rows.filter(x=>x.collar===collar&&x.day<=cut),src=window._raw.filter(x=>x.collar===collar&&x.day<=cut);return{collar,cutoff,calendar_days:g.length,observed_days:g.filter(x=>x.observed).length,coverage:g.length?g.filter(x=>x.observed).length/g.length:0,missing_days:g.filter(x=>!x.observed).length,invalid_coordinate_rows:src.filter(x=>x.qc_bad_coord).length,source_environment_gap_rows:src.filter(x=>x.qc_missing_env).length,long_visit_rows:src.filter(x=>x.qc_long_visit).length,uncertainty:base.latest?.uncertainty??null}}if(name==='compare_population'){const last=Date.parse(`${cutoff}T00:00:00Z`),all=state.rows.filter(x=>x.day===last&&x.observed);return{collar,cutoff,cohort_observed_animals:all.length,animal_speed_z:base.latest?.speed_robust_z??null,cohort_median_speed_z:median(all.map(x=>x.z_speed)),animal_visit_z:base.latest?.visit_robust_z??null,cohort_median_visit_z:median(all.map(x=>x.z_visit)),note:'Population comparison is descriptive and may have uneven animal coverage.'}}throw Error(`Unknown tool ${name}`)}
function deterministicPolicy(collar,cutoff){const trace=[],sig=callTool('inspect_animal_signals',{collar,cutoff}),quality=callTool('assess_data_quality',{collar,cutoff}),env=callTool('inspect_environment',{collar,cutoff});trace.push({tool:'inspect_animal_signals',result:sig},{tool:'assess_data_quality',result:quality},{tool:'inspect_environment',result:env});if(!sig.available)return{action:'HUMAN_REVIEW',priority:'LOW',confidence:0.1,summary:'No usable observations are available before this cutoff.',evidence:[],uncertainty:1,cutoff,collar,trace};const zS=Math.abs(sig.latest.speed_robust_z||0),zV=Math.abs(sig.latest.visit_robust_z||0),cp=!!(sig.latest.changepoint_speed||sig.latest.changepoint_visit),lowQ=quality.coverage<.65||quality.uncertainty>.4,envDry=Number.isFinite(env.mean_rain_30d)&&env.mean_rain_30d<2,flag=!!sig.latest.anomaly_flag||Math.max(zS,zV)>=3,score=(zS>=2?1:0)+(zV>=2?1:0)+(cp?1:0)+(flag?1:0);let action='ROUTINE_MONITORING',priority='LOW',summary='No persistent multi-signal deviation is present in the latest observation window.';if(lowQ){action='OBSERVATION_REQUESTED';priority='MODERATE';summary='Recent coverage is limited; review observation completeness before interpreting signal changes.'}else if(score>=3){action='HUMAN_ESCALATION';priority='HIGH';summary='Multiple processed channels or a persistent deviation support prompt human review.'}else if(flag||cp||score>=1){action='ANOMALY_FLAGGED';priority='MODERATE';summary='A movement or visitation signal warrants review alongside its coverage and context.'}if(envDry&&flag&&action==='ANOMALY_FLAGGED'){summary+=' Low recent rainfall is contextual evidence only; it does not establish water scarcity.'}const evidence=[['speed_robust_z',sig.latest.speed_robust_z],['visit_robust_z',sig.latest.visit_robust_z],['persistent_candidate_flag',sig.latest.anomaly_flag],['change_point_speed',sig.latest.changepoint_speed],['change_point_visitation',sig.latest.changepoint_visit],['coverage_14d',sig.latest.quality14],['uncertainty',sig.latest.uncertainty],['mean_rain_30d_mm',env.mean_rain_30d]].map(([feature,value])=>({feature,value}));return{action,priority,confidence:Math.max(.15,Math.min(.86,.42+score*.1-quality.uncertainty*.3)),summary,collar,cutoff,latest_observed_day:sig.latest_observed_day,evidence,uncertainty:sig.latest.uncertainty,review_required:true,trace}}
function renderAgent(){const a=state.agent,cutoff=currentRows().filter(r=>r.observed).at(-1)?.dateText||'';return pageHead('DECISION SYSTEM','Agentic monitoring','Structured tools read the same causal features shown in the signal pages. Human review remains in the loop.',`${collarSelect()}`)+`<div class="page-callout"><span class="callout-icon">✳</span><div><strong>Two operating modes.</strong> The deterministic policy is fully local and always available. Optional Groq can request read-only tools, then produce a constrained structured recommendation.</div></div><div class="toolbar"><label>HISTORICAL CUTOFF</label>${dateInput(currentRows())}<span class="spacer"></span><span class="section-tag">NO FUTURE ROWS INCLUDED</span><button class="button primary" data-action="run-policy">Run deterministic policy</button><button class="button secondary" data-action="run-groq">Run Groq agent</button></div>${a?`<div class="agent-layout"><div>${card('Structured decision',`${a.source==='groq'?'Groq tool-calling agent':'Local deterministic policy'} · as of ${a.cutoff}`,`<div class="decision-box"><div class="action">${escapeHTML(a.decision.action)} · ${escapeHTML(a.decision.priority)} PRIORITY</div><p>${escapeHTML(a.decision.summary)}</p><div class="grid three-col"><div class="small-stat"><span>Confidence</span><b>${fmt(a.decision.confidence*100,0)}%</b><small>heuristic, not calibrated</small></div><div class="small-stat"><span>Uncertainty</span><b>${fmt((a.decision.uncertainty||0)*100,0)}%</b><small>coverage derived</small></div><div class="small-stat"><span>Review</span><b>Required</b><small>no autonomous dispatch</small></div></div></div><div class="card-title" style="margin:12px 0 8px">Evidence bundle</div><pre class="json-block">${escapeHTML(JSON.stringify(a.decision,null,2))}</pre><button class="button primary" style="margin-top:10px" data-action="save-decision">Save decision to local log</button><div class="status-line" id="agentStatus"></div>`)}</div><div>${card('Tool call trace',`${a.trace.length} structured reads · ${a.elapsed||'local'}`,`<div class="trace">${a.trace.map((t,i)=>`<div class="trace-step"><b>${String(i+1).padStart(2,'0')} · ${escapeHTML(t.tool)}</b><small>${escapeHTML(JSON.stringify(t.result).slice(0,450))}${JSON.stringify(t.result).length>450?'…':''}</small></div>`).join('')}</div>`)}</div></div>`:`<div class="empty-state card"><b>Ready to inspect a collar</b>Select a historical cutoff, then run the local policy or the optional Groq agent. The tool trace will show which processed evidence supported the decision.</div>`}<div style="margin-top:13px">${card('Recent decision log',`${state.decisionLog.length} locally saved records`,`<div class="head-actions" style="justify-content:flex-start"><button class="button secondary" data-action="export-log">Export log ↓</button><button class="button ghost" data-action="clear-log">Clear local log</button></div>${state.decisionLog.length?`<div class="table-wrap" style="margin-top:10px"><table class="data-table"><thead><tr><th>RECORDED AT</th><th>COLLAR</th><th>CUTOFF</th><th>MODE</th><th>ACTION</th><th>PRIORITY</th></tr></thead><tbody>${state.decisionLog.slice().reverse().slice(0,30).map(r=>`<tr><td>${escapeHTML(r.recorded_at)}</td><td>${escapeHTML(r.collar)}</td><td>${escapeHTML(r.cutoff)}</td><td>${escapeHTML(r.source)}</td><td>${escapeHTML(r.action)}</td><td>${escapeHTML(r.priority)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state">Run and save a decision to create a local history.</div>`}`)}</div><div class="footer-note">Local storage is browser-profile scoped and can be cleared. It is not a managed audit service. The optional API receives the tool output when the Groq mode runs.</div>`}
function cutoffValue(){return document.getElementById('cutoffDate')?.value||currentRows().filter(r=>r.observed).at(-1)?.dateText}
function runPolicy(){const start=performance.now(),cutoff=cutoffValue(),decision=deterministicPolicy(state.collar,cutoff);state.agent={source:'deterministic',cutoff,decision,trace:decision.trace,elapsed:`${(performance.now()-start).toFixed(1)} ms`};render()}
function saveDecision(){if(!state.agent)return;const d=state.agent.decision;const row={recorded_at:new Date().toISOString(),collar:state.collar,cutoff:state.agent.cutoff,source:state.agent.source,action:d.action,priority:d.priority,confidence:d.confidence,uncertainty:d.uncertainty,summary:d.summary,decision_json:JSON.stringify(d),tool_trace_json:JSON.stringify(state.agent.trace)};state.decisionLog.push(row);localStorage.setItem('khulansense-decisions',JSON.stringify(state.decisionLog));render()}
function renderGroqEvaluation(x){const e=x.groqEvaluation;if(!e)return card('Optional Groq agent evaluation','Small matched sample · only runs after an explicit click',`<p class="muted" style="line-height:1.6">Scores event response at onset and action rate on sampled unlabeled background cases. The same sample includes fixed, signal-only and adaptive onset decisions. Up to 24 cases require up to 48 Groq requests; API latency and cost depend on the selected model.</p><div class="notice">The model does not receive the synthetic ground-truth label. This stochastic sample is exploratory and is not a fair or definitive superiority test.</div>`,`<button class="button secondary" style="margin-top:10px" data-action="run-groq-experiment">Run matched Groq sample</button>`);if(e.status==='running')return card('Groq agent evaluation','Explicit sample run · deterministic policies remain available',`<div class="page-callout"><span class="spinner"></span><div id="groqEvalStatus">Preparing ${e.total} matched cases…</div></div>`);if(e.status==='error')return card('Groq sample could not finish','Baseline experiment results remain available',`<div class="notice">${escapeHTML(e.message)}</div><div class="status-line">Completed before error: ${e.cases?.length||0} cases.</div>`);const comp=e.comparison;return card('Groq agent sample results',`${e.sample_events} synthetic event onsets · ${e.sample_background_cases} unlabeled background cases · ${fmt(e.elapsed_ms,0)} ms`,`<div class="grid metrics">${metric('EVENT RESPONSE AT ONSET',fmt(e.event_response_rate*100,1)+'%','Groq action on matched synthetic sample',true)}${metric('BACKGROUND ACTION RATE',fmt(e.background_action_rate*100,1)+'%','sampled unlabeled background days')}${metric('FIXED BASELINE',fmt(comp.fixed_event_response*100,1)+'%','same event-onset sample')}${metric('SIGNAL-ONLY BASELINE',fmt(comp.signal_event_response*100,1)+'%','same event-onset sample')}${metric('ADAPTIVE BASELINE',fmt(comp.adaptive_event_response*100,1)+'%','same event-onset sample')}</div><div class="notice">Groq decisions are sampled at event onset, so this comparison reports onset response only. Background cases have no ecological labels; this is an exploratory sample, not a model ranking.</div><div class="table-wrap" style="margin-top:10px"><table class="data-table"><thead><tr><th>CASE</th><th>COLLAR</th><th>CUTOFF</th><th>GROQ ACTION</th><th>PRIORITY</th><th>TOOL</th></tr></thead><tbody>${e.cases.map(r=>`<tr><td><span class="pill ${r.label==='synthetic_event'?'warn':'neutral'}">${r.label==='synthetic_event'?'SYNTHETIC EVENT':'BACKGROUND'}</span></td><td>${escapeHTML(r.collar)}</td><td>${escapeHTML(r.cutoff)}</td><td>${escapeHTML(r.action)}</td><td>${escapeHTML(r.priority||'—')}</td><td>${escapeHTML(r.tool_name)}</td></tr>`).join('')}</tbody></table></div><button class="button secondary" style="margin-top:10px" data-action="export-groq-evaluation">Export Groq sample JSON ↓</button>`)}
function renderExperiments(){const x=state.experiment;return pageHead('RETROSPECTIVE EVALUATION','Experiments','Compare monitoring policies on reproducible, labeled synthetic signal shifts.')+`<div class="page-callout"><span class="callout-icon">⤧</span><div><strong>Synthetic stress test, not wildlife ground truth.</strong> Artificial deviations are injected into standardized feature streams to compare monitoring rules under controlled conditions. They do not represent observed scarcity or validate field performance.</div></div><div class="card" style="margin-bottom:13px"><div class="card-head"><div><div class="card-title">Experiment design</div><div class="card-subtitle">All policies see the same seeded event windows and natural background days.</div></div><span class="section-tag">DETERMINISTIC · LOCAL</span></div><div class="experiment-controls"><div class="range-row"><label for="seedInput">Random seed</label><input id="seedInput" class="text-input" value="20261104" type="number" style="width:125px"></div><div class="range-row"><label for="eventsInput">Synthetic events / collar</label><select id="eventsInput" class="select"><option value="2">2 · quick</option><option value="4" selected>4 · balanced</option><option value="6">6 · broad coverage</option></select></div><div class="range-row"><label for="scheduleInput">Fixed schedule cadence</label><select id="scheduleInput" class="select"><option value="14">14 days</option><option value="30" selected>30 days</option><option value="60">60 days</option></select></div><button class="button primary" data-action="run-experiment">Run experiment</button>${x?'<button class="button secondary" data-action="export-results">Export trial rows ↓</button>':''}</div></div>${x?renderExperimentResults(x):`<div class="empty-state card"><b>Experiment is ready to run</b>Choose a seed and run the benchmark. Metrics appear only after the browser executes the defined trials.</div>`}<div class="footer-note">${x?renderGroqEvaluation(x):''}Baseline definitions and metric formulas are documented in <a href="/docs/experiment_protocol.md" target="_blank">the experiment protocol</a>. Groq is not run implicitly or scored as if it were deterministic.</div>`}
function renderExperimentResults(x){const vals=x.metrics,series=['Fixed schedule','Signal only','Adaptive'].map((n,i)=>({name:n,color:[COLORS.gray,COLORS.blue,COLORS.green][i],values:[{x:0,y:vals[n].recall*100,tip:n}]}));return`<div class="grid metrics">${metric('SYNTHETIC EVENTS',x.eventCount,'known injected labels',true)}${metric('ANIMALS IN TRIAL',x.animalCount,'from study cohort')}${metric('BACKGROUND ANIMAL-DAYS',x.backgroundDays.toLocaleString(),'observed non-event rows')}${metric('MEASURED RUN TIME',fmt(x.elapsedMs,0)+' ms','in this browser session')}${metric('RANDOM SEED',x.seed,'reproducible generator')}</div><div class="grid split equal"><div>${card('Synthetic event recall','Share of injected events with an alert inside the labeled interval',`<div class="chart">${chartSVG(['Fixed schedule','Signal only','Adaptive'].map((n,i)=>({name:n,color:[COLORS.gray,COLORS.blue,COLORS.green][i],values:[{x:i,y:vals[n].recall*100,tip:`${n}: ${fmt(vals[n].recall*100,1)}%`}],type:'bar'})),{height:220,labels:false,zero:true,yTitle:'event recall %'})}</div>${legend([['Fixed schedule',COLORS.gray],['Signal only',COLORS.blue],['Adaptive',COLORS.green]])}`)}</div><div>${card('Background trigger-day rate','Action-days on observed, unlabeled background · per 100 days',`<div class="chart">${chartSVG(['Fixed schedule','Signal only','Adaptive'].map((n,i)=>({name:n,color:[COLORS.gray,COLORS.blue,COLORS.green][i],values:[{x:i,y:vals[n].backgroundTriggerDaysPer100,tip:`${n}: ${fmt(vals[n].backgroundTriggerDaysPer100,2)} /100d`}],type:'bar'})),{height:220,labels:false,zero:true,yTitle:'trigger-days / 100 d'})}</div>`)}</div></div><div class="grid split equal"><div>${card('Detection delay','Median days from synthetic onset to first alert · lower is faster',`<div class="chart">${chartSVG(['Fixed schedule','Signal only','Adaptive'].map((n,i)=>({name:n,color:[COLORS.gray,COLORS.blue,COLORS.green][i],values:[{x:i,y:vals[n].medianDelay,tip:`${n}: ${fmt(vals[n].medianDelay,1)} days`}],type:'bar'})),{height:220,labels:false,zero:true,yTitle:'days'})}</div>`)}</div><div>${card('Channel ablation','Signal-only response recall by injected event mode',`<div class="chart">${chartSVG(['Movement only','Visitation only','Fused'].map((n,i)=>({name:n,color:[COLORS.blue,COLORS.amber,COLORS.green][i],values:[{x:i,y:x.ablation[n].recall*100,tip:`${n}: ${fmt(x.ablation[n].recall*100,1)}%`}],type:'bar'})),{height:220,labels:false,zero:true,yTitle:'event recall %'})}</div><div class="footer-note">Ablation operates on the same injected standardized channels; this isolates rule response, not full pipeline component causality.</div>`)}</div></div>${card('Metrics by policy','Trial-level event labels and false-alert counts',`<div class="table-wrap"><table class="data-table"><thead><tr><th>POLICY</th><th>EVENT RECALL</th><th>FALSE ALERTS / 100D</th><th>MEDIAN DELAY</th><th>ACTION-DAYS</th><th>TRIAL TIME (MS)</th></tr></thead><tbody>${['Fixed schedule','Signal only','Adaptive'].map(n=>`<tr><td>${n}</td><td>${fmt(vals[n].recall*100,1)}%</td><td>${fmt(vals[n].backgroundTriggerDaysPer100,2)}</td><td>${fmt(vals[n].medianDelay,1)} d</td><td>${vals[n].actionDays}</td><td>${fmt(x.elapsedMs,0)}</td></tr>`).join('')}</tbody></table></div><div class="table-caption">These outputs were generated by this run. Event labels are synthetic and no superiority claim is implied.</div>`)}${card('Run manifest','Configuration, controlled shifts and policy rules',`<pre class="json-block">${escapeHTML(JSON.stringify({seed:x.seed,events_per_collar:x.eventsPerCollar,fixed_schedule_days:x.schedule,synthetic_event_styles:['movement shift','visitation shift','coupled shift'],duration_days:'6–10',shift_magnitude_z:'2.3–4.1; deterministic randomized',quality_guard:'low coverage routes adaptive policy to observation request',background_alert_definition:'policy action outside injected intervals'},null,2))}</pre>`)}`}
function mulberry(seed){let t=seed>>>0;return()=>{t+=0x6D2B79F5;let x=t;x=Math.imul(x^x>>>15,x|1);x^=x+Math.imul(x^x>>>7,x|61);return((x^x>>>14)>>>0)/4294967296}}
function runExperiment(){const seed=Number(document.getElementById('seedInput')?.value)||1,eventsPer=Number(document.getElementById('eventsInput')?.value)||4,schedule=Number(document.getElementById('scheduleInput')?.value)||30,rng=mulberry(seed),started=performance.now(),daily=[],allByAnimal=new Map();for(const c of state.collars){const g=state.rows.filter(r=>r.collar===c&&r.observed&&Number.isFinite(r.z_speed)&&Number.isFinite(r.z_visit));if(g.length<200)continue;allByAnimal.set(c,g);const n=Math.min(eventsPer,Math.max(1,Math.floor(g.length/100))),used=new Set();for(let i=0;i<n;i++){let idx=80+Math.floor(rng()*Math.max(1,g.length-100)),attempt=0;while(attempt<30&&[...used].some(u=>Math.abs(u-idx)<20)){idx=80+Math.floor(rng()*Math.max(1,g.length-100));attempt++}used.add(idx);const style=['movement','visitation','coupled'][Math.floor(rng()*3)],duration=[6,7,10][Math.floor(rng()*3)],amp=2.3+rng()*1.8,sign=rng()<.5?-1:1,start=g[idx].day,baseline=g[idx];daily.push({event_id:`S${String(daily.length+1).padStart(4,'0')}`,collar:c,start,duration,style,amp,sign,base:baseline,rows:g})}}
 const events=daily.map(e=>{const series=e.rows.filter(r=>r.day>=e.start&&r.day<e.start+e.duration*86400000),hit={fixed:null,signal:null,adaptive:null,movement:null,visitation:null,fused:null};let firstEvidence=null;for(const r of series){const offset=(r.day-e.start)/86400000,noise=(rng()-.5)*.8,add=e.amp+noise,sz=(Number.isFinite(r.z_speed)?r.z_speed:0)+(e.style!=='visitation'?e.sign*add:0),vz=(Number.isFinite(r.z_visit)?r.z_visit:0)+(e.style!=='movement'?e.sign*add*(e.style==='coupled'?.8:1):0),quality=r.quality14,cp=!!(r.changepoint_speed||r.changepoint_visit),signal=Math.max(Math.abs(sz),Math.abs(vz))>=2.8,adaptive=quality<.55?false:(Math.abs(sz)>=3.3||Math.abs(vz)>=3.3||(Math.abs(sz)>=2.1&&Math.abs(vz)>=2.1)||(cp&&(Math.abs(sz)>=1.8||Math.abs(vz)>=1.8))),fixed=((Math.floor((r.day-e.rows[0].day)/86400000)%schedule)===0),move=Math.abs(sz)>=2.8,visit=Math.abs(vz)>=2.8,fused=signal;if(hit.fixed===null&&fixed)hit.fixed=offset;if(hit.signal===null&&signal)hit.signal=offset;if(hit.adaptive===null&&adaptive)hit.adaptive=offset;if(hit.movement===null&&move)hit.movement=offset;if(hit.visitation===null&&visit)hit.visitation=offset;if(hit.fused===null&&fused)hit.fused=offset;if(offset===0)firstEvidence={collar:e.collar,cutoff:r.dateText,features:{speed_z:sz,visit_z:vz,quality14:quality,uncertainty:r.uncertainty,rain_30d:r.rain_30d,ndvi:r.ndvi,snow:r.snow,change_point:cp},baseline_at_onset:{fixed,signal,adaptive,movement:move,visitation:visit}}}return{...e,hits:hit,firstEvidence}});
 const policies=['Fixed schedule','Signal only','Adaptive'],metrics={},ablation={};const labeledDays=new Set();for(const e of events)for(let d=e.start;d<e.start+e.duration*86400000;d+=86400000)labeledDays.add(`${e.collar}:${d}`);const bgDays=[...allByAnimal.values()].reduce((s,g)=>s+g.length,0)-labeledDays.size;for(const [name,key] of policies.map((n,i)=>[n,['fixed','signal','adaptive'][i]])){const detected=events.filter(e=>e.hits[key]!==null),miss=events.length-detected.length;let alertsBg=0;for(const [c,g] of allByAnimal){for(const r of g){if(labeledDays.has(`${c}:${r.day}`))continue;const idx=Math.floor((r.day-g[0].day)/86400000),zs=Math.abs(Number.isFinite(r.z_speed)?r.z_speed:0),zv=Math.abs(Number.isFinite(r.z_visit)?r.z_visit:0);if(key==='fixed'&&idx%schedule===0)alertsBg++;else if(key==='signal'&&Math.max(zs,zv)>=2.8)alertsBg++;else if(key==='adaptive'&&r.quality14>=.55&&(zs>=3.3||zv>=3.3||(zs>=2.1&&zv>=2.1)))alertsBg++}}metrics[name]={recall:events.length?detected.length/events.length:0,medianDelay:detected.length?median(detected.map(e=>e.hits[key])):NaN,backgroundTriggerDaysPer100:bgDays?alertsBg/bgDays*100:0,actionDays:detected.length+alertsBg,missed:miss}}
 for(const [name,key] of [['Movement only','movement'],['Visitation only','visitation'],['Fused','fused']]){const hit=events.filter(e=>e.hits[key]!==null).length;ablation[name]={recall:events.length?hit/events.length:0,events:events.length}}
 const eventPool=events.map(e=>({...e.firstEvidence,label:'synthetic_event',truth:true,event_id:e.event_id}));for(let i=eventPool.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[eventPool[i],eventPool[j]]=[eventPool[j],eventPool[i]]}const evalCases=eventPool.slice(0,Math.min(12,eventPool.length));const labeledSet=new Set();for(const e of events)for(let d=e.start;d<e.start+e.duration*86400000;d+=86400000)labeledSet.add(`${e.collar}:${d}`);const bgPool=[];for(const[c,g]of allByAnimal)for(const r of g)if(!labeledSet.has(`${c}:${r.day}`))bgPool.push({collar:c,cutoff:r.dateText,truth:false,label:'background',features:{speed_z:r.z_speed,visit_z:r.z_visit,quality14:r.quality14,uncertainty:r.uncertainty,rain_30d:r.rain_30d,ndvi:r.ndvi,snow:r.snow,change_point:!!(r.changepoint_speed||r.changepoint_visit)},baseline_at_onset:{fixed:Math.floor((r.day-g[0].day)/86400000)%schedule===0,signal:Math.max(Math.abs(r.z_speed||0),Math.abs(r.z_visit||0))>=2.8,adaptive:r.quality14>=.55&&(Math.abs(r.z_speed||0)>=3.3||Math.abs(r.z_visit||0)>=3.3||(Math.abs(r.z_speed||0)>=2.1&&Math.abs(r.z_visit||0)>=2.1)),movement:Math.abs(r.z_speed||0)>=2.8,visitation:Math.abs(r.z_visit||0)>=2.8}});for(let i=bgPool.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[bgPool[i],bgPool[j]]=[bgPool[j],bgPool[i]]}evalCases.push(...bgPool.slice(0,Math.min(12,bgPool.length)));state.experimentCases=evalCases;
 const trials=[];for(const e of events)for(const n of policies){const key={ 'Fixed schedule':'fixed','Signal only':'signal','Adaptive':'adaptive'}[n],delay=e.hits[key];trials.push({event_id:e.event_id,collar:e.collar,synthetic_start:dayKey(new Date(e.start)),duration_days:e.duration,synthetic_type:e.style,shift_amplitude_z:e.amp,policy:n,detected:delay!==null,delay_days:delay??'',seed})}const elapsedMs=performance.now()-started;state.experiment={seed,eventsPerCollar:eventsPer,schedule,eventCount:events.length,animalCount:new Set(events.map(e=>e.collar)).size,backgroundDays:bgDays,metrics,ablation,trials,elapsedMs,groqEvaluation:null};render()}
const EVAL_TOOL={type:'function',function:{name:'inspect_evaluation_features',description:'Read the processed and, for an explicitly labeled benchmark case, synthetically perturbed standardized signal values at this historical cutoff. Do not infer ecological ground truth.',parameters:{type:'object',properties:{case_id:{type:'integer'}},required:['case_id'],additionalProperties:false}}};
function renderMethods(){return pageHead('RESEARCH RECORD','Methods & scope','How the signal foundation, decision system and experiments fit together.')+`<div class="grid split equal"><div>${card('Research question','Signal processing and agentic monitoring',`<p class="muted" style="line-height:1.7">Can causal, quality-aware fusion of movement, visitation and environmental context improve monitoring priorities over fixed schedules or single-threshold rules, while preserving transparent evidence for human review?</p><div class="notice"><strong>Original contribution.</strong> A replayable wildlife-monitoring interface that joins causal signal processing, explicit uncertainty, structured tool use and controlled policy evaluation in one evidence chain.</div>`)}</div><div>${card('Study data','Payne et al. (2020) · Dryad',`<div class="activity-list"><div class="activity-row"><span class="activity-mark"></span><div><b>Daily collar observations</b><small>2 source CSVs · ${window._raw.length.toLocaleString()} rows · ${state.collars.length} animals · 2013–2018.</small></div></div><div class="activity-row"><span class="activity-mark warn"></span><div><b>Reported daily centroids</b><small>Coordinates are not raw GPS fixes; movement uses inter-centroid displacement.</small></div></div><div class="activity-row"><span class="activity-mark"></span><div><b>Aggregate waterpoint descriptors</b><small>No waterpoint coordinates; clusters are not presented as verified locations.</small></div></div></div><p class="footer-note"><a href="https://doi.org/10.5061/dryad.pg4f4qrjw" target="_blank" rel="noreferrer">Open Dryad source record ↗</a></p>`)}</div></div><div class="grid split equal"><div>${card('Signal pipeline','Causal transformations',`<div class="activity-list"><div class="activity-row"><span class="activity-mark"></span><div><b>Validate & preserve</b><small>Range and duration flags retained on source rows; missing calendar days remain explicitly unobserved.</small></div></div><div class="activity-row"><span class="activity-mark"></span><div><b>Derive movement</b><small>Haversine centroid displacement / elapsed days; gaps above three days excluded.</small></div></div><div class="activity-row"><span class="activity-mark"></span><div><b>Filter signals</b><small>Trailing Hampel despike, trailing mean, 7/30-day visit rates, lagged robust median/MAD baseline.</small></div></div><div class="activity-row"><span class="activity-mark"></span><div><b>Flag & quantify uncertainty</b><small>Two-sided CUSUM change points, persistence, 14-day coverage-based uncertainty.</small></div></div></div>`)}</div><div>${card('Agent and evaluation','Integrated evidence path',`<div class="activity-list"><div class="activity-row"><span class="activity-mark"></span><div><b>Structured read-only tools</b><small>Signals, environmental context, data quality, and cohort comparison use a shared historical cutoff.</small></div></div><div class="activity-row"><span class="activity-mark warn"></span><div><b>Deterministic monitoring policy</b><small>Local, key-free and visible; the LLM is optional and does not replace the policy.</small></div></div><div class="activity-row"><span class="activity-mark"></span><div><b>Policy benchmark</b><small>Fixed cadence, signal threshold, adaptive evidence-quality rule; synthetic shifts with reproducible labels.</small></div></div><div class="activity-row"><span class="activity-mark alert"></span><div><b>Interpret carefully</b><small>Synthetic results test rule behavior under injection, not ecological generalization.</small></div></div></div>`)}</div></div><div class="grid split equal"><div>${card('Hackathon rubric alignment','As supplied in the project brief',`<div class="activity-list"><div class="activity-row"><span class="activity-mark"></span><div><b>Technical integration & depth · 25 points</b><small>12 signal-processing points and 13 agentic-AI points motivate the linked evidence/tool design.</small></div></div><div class="activity-row"><span class="activity-mark"></span><div><b>Evaluation · 20 points</b><small>Baseline comparisons, task metrics, controlled events and transparent scope.</small></div></div><div class="activity-row"><span class="activity-mark"></span><div><b>Novelty & originality · 15 points</b><small>Quality-aware causal replay and evidence-linked tool use for remote wildlife monitoring.</small></div></div><div class="activity-row"><span class="activity-mark"></span><div><b>Significance · 10 · Scalability · 15</b><small>Wildlife monitoring relevance and specific follow-up research questions are documented.</small></div></div><div class="activity-row"><span class="activity-mark"></span><div><b>Prototype evidence · 10 · Reproducibility · 5</b><small>Local source, actual output exports, run manifest, seed, setup and limitations.</small></div></div></div>`)}</div><div>${card('Research next steps','Questions to test with field-validated data',`<ol class="muted" style="font-size:11px;line-height:1.9;padding-left:18px"><li>How sensitive are alerts to centroid uncertainty and irregular collar schedules?</li><li>Can externally validated waterpoint and precipitation data explain specific signal shifts?</li><li>Do quality-aware abstention rules reduce field review burden without delaying verified events?</li><li>How do thresholds transfer to other years, herds and steppe regions?</li></ol><div class="notice">A field study would require independent labels, a pre-registered event definition and human review.</div>`)}</div></div><div class="footer-note">Source reference: Payne et al., Dryad DOI 10.5061/dryad.pg4f4qrjw. Methods and caveats also available in <a href="/docs/methodology.md" target="_blank">docs/methodology.md</a> and <a href="/docs/limitations.md" target="_blank">docs/limitations.md</a>.</div>`}
function render(){if(!state.rows.length)return;const pages={overview:renderOverview,animal:renderAnimal,movement:renderMovement,visitation:renderVisitation,environment:renderEnvironment,population:()=>renderPopulation()+renderSupplementaryPopulation(),anomalies:renderAnomalies,quality:renderQuality,agent:renderAgent,decisionlog:renderDecisionLog,experiments:renderExperiments,methods:renderMethods};app.innerHTML=pages[state.page]();bindPage()}
// Keep the existing settings experience while sending the key directly to the localhost backend.
const originalWireGlobal=wireGlobal;
wireGlobal=function(){
  originalWireGlobal();
  fetch('/api/groq/status').then(r=>r.json()).then(x=>{state.groqConfigured=!!x.configured;state.model=x.model||state.model;const m=document.getElementById('modelName');if(m)m.value=state.model}).catch(()=>{});
  document.getElementById('saveSettings').onclick=async()=>{
    const input=document.getElementById('apiKey'),key=input.value.trim();if(!key){document.getElementById('settingsStatus').textContent='Enter a Groq API key.';return}
    const b=document.getElementById('saveSettings');b.disabled=true;document.getElementById('settingsStatus').textContent='Checking account model access…';
    try{const r=await fetch('/api/groq/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apiKey:key})}),d=await r.json();if(!r.ok)throw new Error(d.error?.message||'Could not configure Groq.');state.groqConfigured=true;state.model=d.model;document.getElementById('modelName').value=d.model;document.getElementById('settingsStatus').textContent='Connected · '+d.model+'. Key held in backend memory only.';input.value='';}
    catch(e){document.getElementById('settingsStatus').textContent=e.message;input.value='';}
    finally{b.disabled=false}
  };
  document.getElementById('clearKey').onclick=async()=>{try{const r=await fetch('/api/groq/config',{method:'DELETE'});const d=await r.json();state.groqConfigured=!!d.configured;document.getElementById('settingsStatus').textContent=d.message}catch{document.getElementById('settingsStatus').textContent='Could not reach the local backend.'}document.getElementById('apiKey').value=''};
  const test=document.getElementById('testGroqConnection');if(test)test.onclick=async()=>{test.disabled=true;document.getElementById('settingsStatus').textContent='Testing model, chat, tool call and tool-result round trip…';try{const r=await fetch('/api/groq/test',{method:'POST'}),d=await r.json();if(!r.ok)throw new Error(d.error?.message||'Groq connection test failed.');document.getElementById('settingsStatus').textContent='All checks passed · '+d.model+' · chat + tool use + JSON.'}catch(e){document.getElementById('settingsStatus').textContent=e.message}finally{test.disabled=false}};
};
function agentPayload(cutoff){const end=Date.parse(cutoff+'T00:00:00Z');return{collar:state.collar,cutoff,rows:state.rows.filter(r=>r.collar===state.collar&&r.day<=end),sourceQuality:window._raw.filter(r=>r.collar===state.collar&&r.day<=end).map(r=>({collar:r.collar,day:r.day,qc_bad_coord:r.qc_bad_coord,qc_missing_env:r.qc_missing_env,qc_long_visit:r.qc_long_visit})),population:state.rows.filter(r=>r.day===end).map(r=>({day:r.day,observed:r.observed,z_speed:r.z_speed,z_visit:r.z_visit}))}}
async function runGroq(){
  if(!state.groqConfigured){document.getElementById('settingsDialog').showModal();document.getElementById('settingsStatus').textContent='Connect a Groq key in Settings first.';return}
  const cutoff=cutoffValue(),start=performance.now();state.agent={source:'Groq agent',status:'running',cutoff,decision:{action:'RUNNING',priority:'—',confidence:0,uncertainty:1,summary:'The backend agent is inspecting evidence…',reasoning:'Waiting for tool results.',evidence:[],review_required:true},trace:[],elapsed:'pending'};render();
  try{const response=await fetch('/api/agent/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(agentPayload(cutoff))}),data=await response.json();if(!response.ok){const e=new Error(data.error?.message||'Agent request failed.');e.code=data.error?.code||'backend_failure';throw e}
    state.agent={source:'groq',status:'success',cutoff,decision:data.decision,trace:data.trace||[],model:data.model,elapsed:(performance.now()-start).toFixed(0)+' ms'};render();
  }catch(e){const invalid=e.code==='invalid_agent_output'||e.code==='invalid_tool_call',policy=deterministicPolicy(state.collar,cutoff);policy.reasoning=policy.summary;policy.summary='Groq '+(invalid?'returned invalid agent output':'request failed')+': '+e.message+' Deterministic fallback: '+policy.summary;state.agent={source:'deterministic fallback',status:invalid?'invalid_output':'fallback',reason:e.message,cutoff,decision:policy,trace:policy.trace,elapsed:(performance.now()-start).toFixed(0)+' ms'};render()}
}
// Route optional benchmark calls through the backend too; the key never enters this bundle's runtime state.
runGroqExperiment=async function(){
  if(!state.groqConfigured){document.getElementById('settingsDialog').showModal();document.getElementById('settingsStatus').textContent='Connect a Groq key in Settings first.';return}
  if(!state.experimentCases.length)return;
  const started=performance.now(),cases=state.experimentCases.slice(0,24);state.experiment.groqEvaluation={status:'running',completed:0,total:cases.length};render();
  try{
    const payload={cases:cases.map(c=>({label:c.label,collar:c.collar,cutoff:c.cutoff,features:c.features,baseline_fixed:c.baseline_at_onset.fixed,baseline_signal_only:c.baseline_at_onset.signal,baseline_adaptive:c.baseline_at_onset.adaptive}))};
    const r=await fetch('/api/groq/evaluate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw new Error(d.error?.message||'Groq evaluation failed.');
    const out=d.cases.map(x=>({...x,tool_name:'inspect_evaluation_features',synthetic_label_used_in_prompt:false,tool_result_json:JSON.stringify(x.tool_result),decision_json:JSON.stringify(x.decision)})),pos=out.filter(x=>x.label==='synthetic_event'),bg=out.filter(x=>x.label==='background'),respond=x=>x.action!=='ROUTINE_MONITORING',rate=a=>a.length?a.filter(respond).length/a.length:NaN;
    state.experiment.groqEvaluation={status:'complete',seed:state.experiment.seed,sample_events:pos.length,sample_background_cases:bg.length,event_response_rate:rate(pos),background_action_rate:rate(bg),comparison:{fixed_event_response:pos.filter(x=>x.baseline_fixed).length/(pos.length||1),signal_event_response:pos.filter(x=>x.baseline_signal_only).length/(pos.length||1),adaptive_event_response:pos.filter(x=>x.baseline_adaptive).length/(pos.length||1)},cases:out,elapsed_ms:performance.now()-started,model:d.model,note:'Small stochastic LLM sample at event onset. Background cases are unlabeled; exploratory only.'};render()
  }catch(e){state.experiment.groqEvaluation={status:'error',message:e.message,elapsed_ms:performance.now()-started,cases:[]};render()}
};
init();
